source(file.path("analysis","00_setup.R"));library(parallel)
primary_split<-split(primary,primary$canonical_pig_id);npig<-length(primary_split)
fit_loa_boot<-function(seed){set.seed(seed);sampled<-sample.int(npig,npig,replace=TRUE);pieces<-lapply(seq_along(sampled),function(i){q<-primary_split[[sampled[i]]];q$boot_pig<-i;q});z<-dplyr::bind_rows(pieces)|>dplyr::mutate(diff=nibp_map-ibp_same_map,meanp=(nibp_map+ibp_same_map)/2)|>dplyr::arrange(boot_pig,meanp);mean_fit<-geepack::geeglm(diff~meanp,id=boot_pig,data=z,family=gaussian,corstr="exchangeable");z$resid_mean<-z$diff-fitted(mean_fit);scatter_fit<-geepack::geeglm(abs(resid_mean)~meanp,id=boot_pig,data=z,family=gaussian,corstr="exchangeable");pressures<-c(60,80,100,120);X<-cbind(1,pressures);mu<-as.vector(X%*%coef(mean_fit));eabs<-as.vector(X%*%coef(scatter_fit));sdhat<-eabs*sqrt(pi/2);data.frame(pressure=pressures,bias=mu,lower_loa=mu-1.96*sdhat,upper_loa=mu+1.96*sdhat)}
cl<-makeCluster(2);on.exit(stopCluster(cl),add=TRUE);clusterEvalQ(cl,{library(dplyr);library(geepack)});clusterExport(cl,c("primary_split","npig","fit_loa_boot"),envir=.GlobalEnv);res<-parallel::parLapply(cl,20261104+seq_len(1000),fit_loa_boot);df<-dplyr::bind_rows(res,.id="bootstrap");summary<-df|>dplyr::group_by(pressure)|>dplyr::summarise(bias_low=quantile(bias,.025),bias_median=median(bias),bias_high=quantile(bias,.975),lower_loa_low=quantile(lower_loa,.025),lower_loa_median=median(lower_loa),lower_loa_high=quantile(lower_loa,.975),upper_loa_low=quantile(upper_loa,.025),upper_loa_median=median(upper_loa),upper_loa_high=quantile(upper_loa,.975),.groups="drop");readr::write_csv(df,file.path("output","LoA_bootstrap_1000.csv"));readr::write_csv(summary,file.path("output","LoA_bootstrap_final_summary.csv"))
